"""Weekly timesheet lines, one per worker, busiest first."""

from typing import Dict, List
from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from collections import Counter

def _check_shifts(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to build a timesheet")
    if any(not shift.worker.strip() for shift in shifts):
        raise ValueError("a shift has a blank worker name")

def _busiest_first(totals: Dict[str, int]) -> List[str]:
    return sorted(
        totals, key=lambda name: (-totals[name], name)
    )

def _line(
    name: str, counts: Counter, totals: Dict[str, int]
) -> str:
    hours = totals[name] / 60
    noun = "shift" if counts[name] == 1 else "shifts"
    text = f"{name}: {counts[name]} {noun}"
    return f"{text}, {hours:.1f} hours"

# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    _check_shifts(shifts)
    counts = Counter(shift.worker for shift in shifts)
    totals = worker_minutes(shifts)
    names = _busiest_first(totals)
    return [_line(name, counts, totals) for name in names]
